mapper.select:
SELECT rp.*, u.real_name as author_name, p.project_name
FROM research_paper rp
LEFT JOIN sys_user u ON rp.author_id = u.id
LEFT JOIN research_project p ON rp.project_id = p.id
WHERE rp.deleted = 0

    AND (rp.title LIKE CONCAT('%',#{keyword},'%') OR rp.journal_name LIKE CONCAT('%',#{keyword},'%'))


    AND rp.type = #{type}


    AND rp.status = #{status}


    AND rp.author_id = #{authorId}

ORDER BY rp.create_time DESC
